import numpy as np


def extract_parameter(matrix, parameter, n_columns=19):
    result = []

    for row in matrix:
        if parameter in row:
            values = [float(x) for x in row[parameter]]

            # Left-pad with zeros
            values = [0.0] * (n_columns - len(values)) + values

            # Keep exactly n_columns
            values = values[-n_columns:]
        else:
            # Parameter missing -> all zeros
            values = [0.0] * n_columns

        result.append(values)

    return result


def print_parameter(matrix, parameter, n_columns=19):
    result = extract_parameter(matrix, parameter, n_columns)

    print("[")

    for row in result:
        print(f"    {row},")

    print("]")


